use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResolvedContextBlock {
    /// Block label.
    pub name: String,
    /// Optional description of the block.
    pub description: Option<String>,
    /// Files generated by this block, keyed by output path.
    pub generates: BTreeMap<String, ResolvedContextBlockTemplate>,
    /// Extension point contributions, keyed by extension point name.
    pub contributes: BTreeMap<String, ResolvedContextBlockContribution>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ResolvedContextBlockContribution {
    Text(ResolvedContextBlockTemplate),
    Tokens(ResolvedContextBlockTemplate),
    CargoDependencies(Vec<ResolvedContextBlockDependency>),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResolvedContextBlockDependency {
    pub name: String,
    pub version: Option<String>,
    pub git: Option<String>,
    pub branch: Option<String>,
    pub tag: Option<String>,
    pub rev: Option<String>,
    pub path: Option<String>,
    pub default_features: Option<bool>,
    pub features: BTreeSet<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResolvedContextBlockTemplate {
    /// Original path as declared in the manifest.
    pub path: String,
    /// Raw template content.
    pub content: String,
}
